// The helpers stay internal, but the kernels below must not: the
// REGISTER_IMPL_TO_DISPATCHER objects are self-registering statics, and internal
// linkage lets the linker discard them as unused. Measured after a change that
// added ops -- the kernels were present in the library and no registrar was, so
// every route reported "backend not registered".
namespace {

// The dtypes a CNNL kernel here serves. Anything else is a TORCH_CHECK rather
// than a fallback: this backend registers the op on PrivateUse1, so a silent
// slow path would re-enter this same function.
bool SupportedFloatDtype(at::ScalarType dtype) {
  return dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16;
}

// CNNL's own half arithmetic measured inaccurate on this SDK, so half and
// bfloat16 compute in float32 and narrow once at the end.
bool ComputesInFloat32(at::ScalarType dtype) { return dtype != at::kFloat; }

cnnlCastDataType_t CastToFloat(at::ScalarType dtype) {
  switch (dtype) {
    case at::kHalf:
      return CNNL_CAST_HALF_TO_FLOAT;
    case at::kBFloat16:
      return CNNL_CAST_BFLOAT16_TO_FLOAT;
    case at::kDouble:
      return CNNL_CAST_DOUBLE_TO_FLOAT;
    default:
      TORCH_CHECK(false, "flagos cambricon: no widening cast for ", dtype);
  }
}

cnnlCastDataType_t CastFromFloat(at::ScalarType dtype) {
  switch (dtype) {
    case at::kHalf:
      return CNNL_CAST_FLOAT_TO_HALF;
    case at::kBFloat16:
      return CNNL_CAST_FLOAT_TO_BFLOAT16;
    default:
      TORCH_CHECK(false, "flagos cambricon: no narrowing cast for ", dtype);
  }
}

at::Tensor Widen(const at::Tensor& input, cnnlHandle_t handle) {
  if (input.scalar_type() == at::kFloat) {
    return input;
  }
  auto output = at::empty(input.sizes(), input.options().dtype(at::kFloat));
  TensorDesc from, to;
  from.Set(input);
  to.Set(output);
  CheckCnnl(
      cnnlCastDataType(handle, from.get(), input.const_data_ptr(),
                       CastToFloat(input.scalar_type()), to.get(),
                       output.mutable_data_ptr()),
      "cnnlCastDataType (widen)");
  return output;
}

// Narrow `wide` into `result`, both dense and the same shape.
void Narrow(const at::Tensor& wide, at::Tensor& result, cnnlHandle_t handle) {
  TensorDesc from, to;
  from.Set(wide);
  to.Set(result);
  CheckCnnl(
      cnnlCastDataType(handle, from.get(), wide.const_data_ptr(),
                       CastFromFloat(result.scalar_type()), to.get(),
                       result.mutable_data_ptr()),
      "cnnlCastDataType (narrow)");
}

// The operand's own shape, right-aligned with `full`, with the axes it
// broadcasts dropped.
//
// CNNL rejects the zero-stride view `expand` produces -- cnnlOpTensor fails
// inside cnnlCopy_v2 with BAD_PARAM -- and materialising that view copies a
// result-sized buffer before the arithmetic starts: measured on an MLU590 for
// one [2,512,1] by [2,512,1024] multiply, 5769 us materialised against 22 us
// for the same multiply without a broadcast. Dropping the axis keeps the
// operand dense at its real size, and cnnlOpTensor broadcasts by position.
std::vector<int64_t> WithoutBroadcastAxes(
    const at::Tensor& tensor, const std::vector<int64_t>& full) {
  const int64_t lead = static_cast<int64_t>(full.size()) - tensor.dim();
  std::vector<int64_t> sizes;
  for (int64_t axis = 0; axis < tensor.dim(); ++axis) {
    if (tensor.size(axis) != 1 || full[lead + axis] == 1) {
      sizes.push_back(tensor.size(axis));
    }
  }
  return sizes.empty() ? std::vector<int64_t>{1} : sizes;
}

at::Tensor NarrowIndices(const at::Tensor& indices, cnnlHandle_t handle) {
  if (indices.scalar_type() == at::kInt) {
    return indices;
  }
  auto narrowed = at::empty(indices.sizes(), indices.options().dtype(at::kInt));
  TensorDesc from, to;
  from.Set(indices);
  to.Set(narrowed);
  CheckCnnl(
      cnnlCastDataType(handle, from.get(), indices.const_data_ptr(),
                       CNNL_CAST_INT64_TO_INT32, to.get(),
                       narrowed.mutable_data_ptr()),
      "cnnlCastDataType (indices)");
  return narrowed;
}

// CNNL documents its index range as [-2^24, 2^24], and the redirect slot the
// embedding backward appends has to be representable in an int32 index.
constexpr int64_t kMaxNumWeights = int64_t{1} << 24;

} // namespace

at::Tensor PrivSafeSoftmaxKernelCambricon(const at::Tensor& self, int64_t dim, std::optional<at::ScalarType> dtype) {
  const at::ScalarType input_dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(input_dtype),
      "flagos cambricon: _safe_softmax does not serve ", input_dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: _safe_softmax requires a device tensor");
  TORCH_CHECK(
      self.dim() > 0,
      "flagos cambricon: _safe_softmax does not serve a zero-rank tensor");
  const int64_t resolved = dim < 0 ? dim + self.dim() : dim;
  TORCH_CHECK(
      resolved == self.dim() - 1,
      "flagos cambricon: _safe_softmax serves the last axis only, got ", dim);
  TORCH_CHECK(
      !dtype.has_value() || *dtype == at::kFloat || *dtype == input_dtype,
      "flagos cambricon: _safe_softmax does not serve the requested dtype");

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const auto wide = Widen(self, handle);
  const bool strided = wide.data_ptr() == self.data_ptr();
  auto output = at::empty(self.sizes(), self.options().dtype(at::kFloat));
  // cnnlSoftmaxForward's LOW_DIMENSION mode reduces the last axis of a
  // three-dimensional descriptor, and rejects anything else: a 4-D
  // (2,16,512,512) descriptor came back "Input and output shapes must be
  // identical and three-dimensional". Folding every leading axis into one keeps
  // the reduced axis in the same place, so the answer is unchanged -- a softmax
  // over the last axis does not care how the rows before it are grouped.
  //
  // The collapsed view is taken with as_strided, not reshape: reshape would copy
  // a non-contiguous operand to make the collapse legal, which is the very copy
  // this kernel avoids.
  // Exactly three dimensions: a probe against this SDK showed rank 2 and rank 4
  // both rejected with "Input and output shapes must be identical and
  // three-dimensional", and rank 3 accepted. So every axis before the last two
  // is folded into one, which moves nothing -- a softmax over the last axis does
  // not care how the rows before it are grouped.
  const int64_t rank = self.dim();
  std::vector<int64_t> folded;
  std::vector<int64_t> folded_strides;
  if (rank <= 3) {
    folded.assign(self.sizes().begin(), self.sizes().end());
    folded_strides.assign(wide.strides().begin(), wide.strides().end());
    while (folded.size() < 3) {
      folded.insert(folded.begin(), 1);
      folded_strides.insert(folded_strides.begin(), 0);
    }
  } else {
    int64_t leading = 1;
    for (int64_t axis = 0; axis + 2 < rank; ++axis) {
      leading *= self.size(axis);
    }
    folded = {leading, self.size(rank - 2), self.size(rank - 1)};
    // Folding axes 0..rank-3 leaves the step between consecutive blocks, which
    // is the stride of the last axis being merged.
    folded_strides = {wide.stride(rank - 3), wide.stride(rank - 2),
                       wide.stride(rank - 1)};
  }
  const auto wide_3d = wide.as_strided(folded, folded_strides);
  auto output_3d = output.as_strided(folded, folded_strides);

  TensorDesc in_desc, out_desc;
  if (strided) {
    in_desc.SetStrided(wide_3d);
  } else {
    in_desc.Set(wide_3d);
  }
  out_desc.Set(output_3d);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetSoftmaxForwardWorkspaceSize(
          handle, in_desc.get(), out_desc.get(), CNNL_SOFTMAX_ACCURATE,
          CNNL_SOFTMAX_MODE_LOW_DIMENSION, &workspace_size),
      "cnnlGetSoftmaxForwardWorkspaceSize");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  const float one = 1.0f;
  const float zero = 0.0f;
  CheckCnnl(
      cnnlSoftmaxForward_v2(
          handle, CNNL_SOFTMAX_ACCURATE, CNNL_SOFTMAX_MODE_LOW_DIMENSION,
          &one, in_desc.get(), wide.const_data_ptr(), &zero, out_desc.get(),
          workspace_size,
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          output.data_ptr()),
      "cnnlSoftmaxForward_v2 (_safe_softmax)");

  // What comes back is the requested dtype when there is one, otherwise the
  // input's: _safe_softmax on a half tensor answers in half, so returning the
  // float32 the kernel computes in would be a different op. Narrowing is one
  // pass, and the widening cast of the input was the other.
  const auto result_dtype = dtype.has_value() ? *dtype : input_dtype;
  if (output.scalar_type() == result_dtype) {
    return output;
  }
  auto result = at::empty(self.sizes(), self.options().dtype(result_dtype));
  Narrow(output, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(PrivSafeSoftmaxFn, priv_safe_softmax_dispatcher, Backend::kCambricon, PrivSafeSoftmaxKernelCambricon);

at::Tensor AbsKernelCambricon(const at::Tensor& self) {
  const at::ScalarType dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: abs does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: abs requires a device tensor");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  // The operand keeps its own strides. In a training step this op is reached
  // through a [B, heads, S, head_dim] transpose view, and gathering that view
  // into a dense buffer costs 15762 us against 13 us for the negation itself --
  // the copy was the whole cost. cnnlNegTensor documents strided descriptors
  // (cnnlSetTensorDescriptorEx), so the view is described as it is.
  //
  // A widening dtype has to be materialised anyway, because the cast produces a
  // dense tensor and there is nothing left to describe.
  const auto wide = Widen(self, handle);
  const bool strided = wide.data_ptr() == self.data_ptr();
  auto output = at::empty(self.sizes(), self.options().dtype(at::kFloat));
  TensorDesc in_desc, out_desc;
  if (strided) {
    in_desc.SetStrided(self);
  } else {
    in_desc.Set(wide);
  }
  out_desc.Set(output);
  CheckCnnl(
      cnnlAbs(
          handle, in_desc.get(), wide.const_data_ptr(), out_desc.get(),
          output.mutable_data_ptr()),
      "cnnlAbs (abs)");
  if (!ComputesInFloat32(dtype)) {
    return output;
  }
  auto result = at::empty(self.sizes(), self.options());
  Narrow(output, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(AbsFn, abs_dispatcher, Backend::kCambricon, AbsKernelCambricon);

at::Tensor AddScalarKernelCambricon(
    const at::Tensor& self, const at::Scalar& other, const at::Scalar& alpha) {
  const at::ScalarType dtype = at::result_type(self, other);
  TORCH_CHECK(
      SupportedFloatDtype(dtype) || dtype == at::kInt,
      "flagos cambricon: add.Scalar does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: add.Scalar requires a device tensor");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const auto input = self.contiguous().to(dtype);
  const bool integral = dtype == at::kInt;
  const bool widen = !integral && ComputesInFloat32(dtype);
  const auto wide_input = widen ? Widen(input, handle) : input;
  const auto compute = integral ? dtype : at::kFloat;

  // The scalar becomes a one-element device tensor. A CNNL descriptor cannot
  // express rank zero, and cnnlOpTensor broadcasts a (1) operand across the
  // operand it is paired with, so this is the shape that carries a scalar.
  // The scalar operand is described at the input's own rank with size 1 on
  // every axis: cnnlOpTensor rejects an operand whose rank differs from the
  // output's (cnnlSetTensorDescriptor fails), and a leading-1 shape broadcasts
  // across every axis.
  std::vector<int64_t> scalar_shape(self.dim(), 1);
  if (scalar_shape.empty()) {
    scalar_shape.push_back(1);
  }
  TORCH_CHECK(
      !scalar_shape.empty() && scalar_shape.size() <= 8,
      "flagos cambricon: scalar rank ", scalar_shape.size(),
      " (input dim ", self.dim(), ")");
  // Filled from a host-side tensor copy: aten's in-place fill_ of a device
  // tensor dispatches through the same op set this backend is serving, so
  // building the scalar with it re-entered the kernel being defined.
  const double value = other.toDouble();
  auto host_scalar = at::empty(scalar_shape, at::kDouble);
  host_scalar.fill_(value);
  auto scalar = host_scalar.to(
      self.options().dtype(integral ? dtype : at::kFloat));

  auto output = at::empty(self.sizes(), self.options().dtype(compute));
  TensorDesc ad, bd, cd;
  ad.Set(wide_input);
  bd.Set(scalar);
  cd.Set(output);
  OpTensorDesc op(CNNL_OP_TENSOR_ADD, compute);
  const float one_f = 1.0f;
  const float zero_f = 0.0f;
  const int32_t one_i = 1;
  const int32_t zero_i = 0;
  const void* aa = integral ? static_cast<const void*>(&one_i) : &one_f;
  const void* bb = integral ? static_cast<const void*>(&zero_i) : &zero_f;
  CheckCnnl(
      cnnlOpTensor(
          handle, op.get(), aa, ad.get(), wide_input.const_data_ptr(), aa,
          bd.get(), scalar.const_data_ptr(), nullptr, 0, bb, cd.get(),
          output.mutable_data_ptr()),
      "cnnlOpTensor (add.Scalar)");
  if (dtype == compute) {
    return output;
  }
  auto result = at::empty(self.sizes(), self.options().dtype(dtype));
  Narrow(output, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(AddScalarFn, add_scalar_dispatcher, Backend::kCambricon, AddScalarKernelCambricon);

at::Tensor AddTensorKernelCambricon(
    const at::Tensor& self, const at::Tensor& other, const at::Scalar& alpha) {
  TORCH_CHECK(
      alpha.toComplexDouble() == 1.0,
      "flagos cambricon: add.Tensor only serves alpha = 1, got ", alpha);
  const at::ScalarType dtype = at::result_type(self, other);
  TORCH_CHECK(
      SupportedFloatDtype(dtype) || dtype == at::kInt,
      "flagos cambricon: add.Tensor does not serve ", dtype);
  const auto device = self.is_cpu() ? other.device() : self.device();
  TORCH_CHECK(
      device.type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: add.Tensor requires a device operand");
  for (const auto* tensor : {&self, &other}) {
    TORCH_CHECK(
        tensor->device() == device || (tensor->is_cpu() && tensor->dim() == 0),
        "flagos cambricon: add.Tensor only accepts CPU tensors as scalars");
  }
  CambriconDeviceGuard guard(self.is_cpu() ? other : self);
  auto a = self.to(device, dtype);
  auto b = other.to(device, dtype);
  const auto shape = at::infer_size(self.sizes(), other.sizes());
  auto result = at::empty(shape, a.options());
  if (result.numel() == 0) {
    return result;
  }
  // A CNNL ARRAY descriptor cannot express rank zero.
  std::vector<int64_t> full(shape.begin(), shape.end());
  if (full.empty()) {
    full.push_back(1);
  }
  const auto handle = HandleForDevice(static_cast<int>(device.index()));
  const bool integral = dtype == at::kInt;
  const bool widen = !integral && ComputesInFloat32(dtype);
  // cnnlOpTensor broadcasts on its own: given [2,4,8] against [2,4,1] it
  // produces the [2,4,8] product (verified against a C probe), and it rejects a
  // reduced-rank or flattened descriptor with status 7. So each operand is
  // described at its own rank and nothing is expanded.
  //
  // Materialising the broadcast was how this was first written, and it copies a
  // result-sized buffer before the arithmetic starts: `add` of [2,512,1] against
  // [2,512,1024] measured 5809 us materialised against 24 us for the same add
  // without a broadcast.
  a = a.contiguous();
  b = b.contiguous();
  // A scalar operand arrives as a rank-0 tensor (`x * 2.0` spells the number
  // that way), and a CNNL descriptor cannot express rank zero. Describing it as
  // one element keeps the broadcast meaning: a single value applies to every
  // element of the other operand.
  const auto as_rank_one = [](const at::Tensor& t) {
    return t.dim() == 0 ? t.reshape({1}) : t;
  };
  const auto a_shaped = widen ? Widen(as_rank_one(a), handle) : as_rank_one(a);
  const auto b_shaped = widen ? Widen(as_rank_one(b), handle) : as_rank_one(b);
  const auto compute = integral ? dtype : at::kFloat;
  auto wide = at::empty(full, a.options().dtype(compute));
  TensorDesc ad, bd, cd;
  ad.Set(a_shaped);
  bd.Set(b_shaped);
  cd.Set(wide);
  OpTensorDesc op(CNNL_OP_TENSOR_ADD, compute);
  const float one = 1.0f;
  const float zero = 0.0f;
  const int32_t int_one = 1;
  const int32_t int_zero = 0;
  const void* scale_a = integral ? static_cast<const void*>(&int_one) : &one;
  const void* scale_b = integral ? static_cast<const void*>(&int_zero) : &zero;
  CheckCnnl(
      cnnlOpTensor(
          handle, op.get(), scale_a, ad.get(), a_shaped.const_data_ptr(),
          scale_a, bd.get(), b_shaped.const_data_ptr(), nullptr, 0, scale_b,
          cd.get(), wide.mutable_data_ptr()),
      "cnnlOpTensor (add.Tensor)");
  if (dtype == compute) {
    return wide.reshape(shape);
  }
  auto output = result.reshape(full);
  Narrow(wide, output, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(AddTensorFn, add_tensor_dispatcher, Backend::kCambricon, AddTensorKernelCambricon);

at::Tensor BmmKernelCambricon(const at::Tensor& self, const at::Tensor& mat2) {
  const at::ScalarType dtype = at::result_type(self, mat2);
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: bmm does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1 &&
          mat2.device() == self.device(),
      "flagos cambricon: bmm needs both operands on one device");
  TORCH_CHECK(
      self.dim() == 3 && mat2.dim() == 3 && self.size(0) == mat2.size(0),
      "flagos cambricon: bmm expects two 3-D operands with one batch size");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(dtype);
  // A transposed operand is described, not copied. `x @ w.t()` is how every
  // Linear layer spells its product, and materialising that view copies the
  // whole weight on every call: measured at 1024x3072, mm(x, w.t()) took 9027 us
  // against 37 us for mm(x, w) -- 242 times slower for the same arithmetic.
  // CNNL expresses it with CNNL_MATMUL_DESC_TRANS* plus the operand's own
  // strides, so both are passed through instead of being normalised away.
  // This is the shape `x @ w.t()` takes in every Linear layer, and copying the
  // weight there made the multiply 242 times slower than the same product on a
  // contiguous operand.
  // A 2-D view whose transpose is contiguous is described by that storage plus
  // the matmul transpose flag; anything else is materialised.
  const bool a_transposed =
      self.dim() == 2 && !self.is_contiguous() && self.t().is_contiguous();
  const bool b_transposed =
      mat2.dim() == 2 && !mat2.is_contiguous() && mat2.t().is_contiguous();
  // With the transpose flag set, CNNL expects each descriptor to describe the
  // operand's *storage*, and applies the transpose itself. So a transposed
  // operand is passed as the contiguous view whose transpose is the logical
  // matrix -- for `w.t()` that view is `w`. The result shape still follows aten's
  // rules, which is why it is computed from the logical operands.
  const auto a = a_transposed ? self.t() : self.contiguous();
  const auto b = b_transposed ? mat2.t() : mat2.contiguous();
  const auto aw = widen ? Widen(a, handle) : a;
  const auto bw = widen ? Widen(b, handle) : b;
  const auto compute = widen ? at::kFloat : dtype;

  const int64_t batch = self.size(0);
  const int64_t rows = self.size(1);
  const int64_t inner = self.size(2);
  const int64_t cols = mat2.size(2);
  auto wide = at::empty({batch, rows, cols}, self.options().dtype(compute));

  // CNNL's matmul is 2-D per call, so the batch axis is iterated here. Each
  // slice is a plain (rows, inner) x (inner, cols) product of contiguous
  // storage, which is exactly what the descriptor pair describes.
  const float one_f = 1.0f;
  const float zero_f = 0.0f;
  const void* alpha = static_cast<const void*>(&one_f);
  const void* beta = static_cast<const void*>(&zero_f);
  // Every batch slice has the same shape, so the descriptor, the algorithm and
  // its workspace are resolved once and reused. Doing that search per slice
  // measured 527 us for a 32-batch bmm, against 22 us for one multiply.
  const auto a_slice = aw[0];
  const auto b_slice = bw[0];
  auto out_slice = wide[0];
  TensorDesc ad, bd, cd;
  ad.Set(a_slice);
  bd.Set(b_slice);
  cd.Set(out_slice);
  cnnlMatMulExDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateMatMulExDescriptor(&desc), "cnnlCreateMatMulExDescriptor");
  cnnlMatMulExAlgo_t algo = nullptr;
  CheckCnnl(cnnlCreateMatMulExAlgo(&algo), "cnnlCreateMatMulExAlgo");
  cnnlMatMulExHeuristicResult_t result_algo = nullptr;
  CheckCnnl(
      cnnlCreateMatMulExHeuristicResult(&result_algo),
      "cnnlCreateMatMulExHeuristicResult");
  cnnlMatMulExPrefer_t prefer{};
  int returned = 0;
  CheckCnnl(
      cnnlGetMatMulExAlgoHeuristic(
          handle, desc, ad.get(), bd.get(), cd.get(), cd.get(), prefer,
          /*requested_algo_count=*/1, &result_algo, &returned),
      "cnnlGetMatMulExAlgoHeuristic (bmm)");
  TORCH_CHECK(returned > 0, "flagos cambricon: no matmul algorithm for bmm");
  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetMatMulExHeuristicResult(result_algo, algo, &workspace_size),
      "cnnlGetMatMulExHeuristicResult");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  for (int64_t index = 0; index < batch; ++index) {
    CheckCnnl(
        cnnlMatMulEx_v2(
            handle, desc, algo, alpha, ad.get(),
            aw[index].const_data_ptr(), bd.get(), bw[index].const_data_ptr(),
            beta, cd.get(), wide[index].mutable_data_ptr(),
            workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
            workspace_size, cd.get(), wide[index].mutable_data_ptr()),
        "cnnlMatMulEx_v2 (bmm)");
  }
  cnnlDestroyMatMulExHeuristicResult(result_algo);
  cnnlDestroyMatMulExAlgo(algo);
  cnnlDestroyMatMulExDescriptor(desc);

  if (!widen) {
    return wide;
  }
  auto result = at::empty({batch, rows, cols}, self.options());
  Narrow(wide, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(BmmFn, bmm_dispatcher, Backend::kCambricon, BmmKernelCambricon);

namespace {

::std::optional<at::Tensor> CloneKernelCambricon(
    const at::Tensor& self, ::std::optional<at::MemoryFormat> memory_format) {
  if (self.device().type() != c10::DeviceType::PrivateUse1) {
    return ::std::nullopt;
  }
  // FLAGOS_OP_clone=<backend> is the conf's per-op override, and clone has no
  // dispatcher slot for it to act on, so the hook reads it itself. Anything but
  // "cambricon" declines, which is how a build can be taken back to the ATen
  // route without being recompiled.
  {
    const char* want = std::getenv("FLAGOS_OP_clone");
    if (want != nullptr && std::strcmp(want, "cambricon") != 0) {
      return ::std::nullopt;
    }
  }
  if (!SupportedFloatDtype(self.scalar_type())) {
    return ::std::nullopt;
  }
  if (memory_format.has_value() &&
      *memory_format != at::MemoryFormat::Contiguous) {
    return ::std::nullopt;
  }
  // An empty tensor has nothing to gather, and describing it as a strided copy
  // is a call for a result that is already correct.
  if (self.numel() == 0) {
    return at::empty(self.sizes(), self.options());
  }

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  auto result = at::empty(self.sizes(), self.options());
  TensorDesc in_desc, out_desc;
  // The source keeps its own strides: that is the whole point, and it is what
  // cnnlSetTensorDescriptorEx is for. It requires the innermost stride to be 1,
  // which is what a view of a dense tensor has.
  in_desc.SetStrided(self);
  out_desc.Set(result);
  CheckCnnl(
      cnnlCopy_v2(
          handle, in_desc.get(), self.const_data_ptr(), out_desc.get(),
          result.mutable_data_ptr(), nullptr, 0),
      "cnnlCopy_v2 (clone)");
  return result;
}

} // namespace (anon)

at::Tensor EmbeddingDenseBackwardKernelCambricon(
    const at::Tensor& grad_output, const at::Tensor& indices,
    int64_t num_weights, int64_t padding_idx, bool scale_grad_by_freq) {
  TORCH_CHECK(
      grad_output.device().type() == c10::DeviceType::PrivateUse1 &&
          indices.device() == grad_output.device(),
      "flagos cambricon: embedding_dense_backward needs both tensors on the "
      "same flagos device");
  const auto dtype = grad_output.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: embedding_dense_backward does not serve ", dtype);
  TORCH_CHECK(
      indices.scalar_type() == at::kLong || indices.scalar_type() == at::kInt,
      "flagos cambricon: embedding indices must be int32 or int64, got ",
      indices.scalar_type());
  TORCH_CHECK(num_weights >= 0, "flagos cambricon: negative num_weights");
  TORCH_CHECK(
      num_weights <= kMaxNumWeights,
      "flagos cambricon: embedding tables larger than 2^24 rows are not served "
      "natively yet, got ",
      num_weights);

  const int64_t width = grad_output.dim() == 0 ? 0 : grad_output.size(-1);
  const int64_t rows = indices.numel();
  TORCH_CHECK(
      grad_output.numel() == rows * width,
      "flagos cambricon: embedding_dense_backward got ", grad_output.numel(),
      " gradient elements for ", rows, " indices of width ", width);

  auto result = at::zeros({num_weights, width}, grad_output.options());
  if (result.numel() == 0 || rows == 0) {{
    return result;
  }}

  CambriconDeviceGuard guard(grad_output);
  const auto handle =
      HandleForDevice(static_cast<int>(grad_output.device().index()));
  const auto grad_dense = grad_output.reshape({{rows, width}}).contiguous();
  auto flat = indices.reshape({{rows}});

  const bool active_padding = padding_idx >= 0 && padding_idx < num_weights;
  const int64_t discarded = num_weights;
  auto compare = flat;
  if (compare.scalar_type() == at::kInt) {{
    compare = compare.to(at::kLong);
  }}
  auto clamped = at::where(compare < 0, discarded, compare);
  clamped = at::where(clamped >= num_weights, discarded, clamped);
  if (active_padding) {{
    clamped = at::where(clamped == padding_idx, discarded, clamped);
  }}
  const auto target = NarrowIndices(clamped.contiguous(), handle).contiguous();

  const bool widen = ComputesInFloat32(dtype);
  auto wide = at::zeros(
      {{num_weights + 1, width}}, grad_output.options().dtype(at::kFloat));
  TensorDesc idx_desc;
  idx_desc.Set(target);
  TensorDesc grad_desc, out_desc;
  at::Tensor grad_fp32;
  if (widen) {
    grad_fp32 =
        at::empty({{rows, width}}, grad_output.options().dtype(at::kFloat));
    TensorDesc from, to;
    from.Set(grad_dense);
    to.Set(grad_fp32);
    CheckCnnl(
        cnnlCastDataType(
            handle, from.get(), grad_dense.const_data_ptr(),
            CastToFloat(dtype), to.get(), grad_fp32.mutable_data_ptr()),
        "cnnlCastDataType (embedding gradient)");
    grad_desc.Set(grad_fp32);
  } else {{
    grad_desc.Set(grad_dense);
  }}
  out_desc.Set(wide);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetEmbeddingBackwardWorkspaceSize(
          handle, grad_desc.get(), out_desc.get(), scale_grad_by_freq,
          &workspace_size),
      "cnnlGetEmbeddingBackwardWorkspaceSize");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {{static_cast<int64_t>(workspace_size)}},
        grad_output.options().dtype(at::kByte));
  }
  // Every index reaching CNNL is a valid table row: padding and out-of-range
  // rows already sit on the discarded slot, so no row is skipped here.
  CheckCnnl(
      cnnlEmbeddingBackward(
          handle, /*padding_idx=*/-1, scale_grad_by_freq, idx_desc.get(),
          target.const_data_ptr(), grad_desc.get(),
          widen ? grad_fp32.const_data_ptr() : grad_dense.const_data_ptr(),
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, out_desc.get(), wide.mutable_data_ptr()),
      "cnnlEmbeddingBackward");

  const auto kept =
      wide.narrow(0, 0, num_weights).reshape({{num_weights, width}}).contiguous();
  if (!widen) {{
    return kept;
  }}
  result.copy_(kept);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(EmbeddingDenseBackwardFn, embedding_dense_backward_dispatcher, Backend::kCambricon, EmbeddingDenseBackwardKernelCambricon);

at::Tensor MeanKernelCambricon(
    const at::Tensor& self, std::optional<at::ScalarType> dtype_opt) {
  const at::ScalarType dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: mean does not serve ", dtype);
  TORCH_CHECK(
      !dtype_opt.has_value() || SupportedFloatDtype(*dtype_opt),
      "flagos cambricon: mean does not serve the requested dtype");
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: mean requires a device tensor");
  TORCH_CHECK(self.numel() > 0, "flagos cambricon: mean of an empty tensor");

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(dtype);
  const auto input = self.contiguous();
  const auto wide_input = widen ? Widen(input, handle) : input;
  const auto compute = widen ? at::kFloat : dtype;

  // Reducing every axis leaves one element, so both sides are described at
  // their flattened rank rather than carrying the operand's shape through.
  std::vector<int64_t> flat_input_shape{input.numel()};
  auto flat_input = wide_input.reshape(flat_input_shape);
  auto flat_out = at::empty({1}, self.options().dtype(compute));
  std::vector<int> axes{0};

  cnnlReduceDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateReduceDescriptor(&desc), "cnnlCreateReduceDescriptor");
  CheckCnnl(
      cnnlSetReduceDescriptor_v3(
          desc, axes.data(), 1, CNNL_REDUCE_AVG, ToCnnlDtype(compute),
          CNNL_NOT_PROPAGATE_NAN, CNNL_REDUCE_NO_INDICES, CNNL_32BIT_INDICES,
          /*p=*/0.0f, /*acc_sqrt=*/false),
      "cnnlSetReduceDescriptor_v3 (mean)");
  TensorDesc in_desc, out_desc;
  in_desc.Set(flat_input);
  out_desc.Set(flat_out);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetReduceOpWorkspaceSize_v2(
          handle, in_desc.get(), out_desc.get(), /*indices_desc=*/nullptr, desc,
          &workspace_size),
      "cnnlGetReduceOpWorkspaceSize_v2 (mean)");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  CheckCnnl(
      cnnlReduce_v2(
          handle, desc, in_desc.get(), flat_input.const_data_ptr(),
          /*alpha=*/nullptr, /*beta=*/nullptr,
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, out_desc.get(), flat_out.mutable_data_ptr(),
          /*indices_desc=*/nullptr, /*indices=*/nullptr),
      "cnnlReduce_v2 (mean)");
  cnnlDestroyReduceDescriptor(desc);

  auto result = at::empty(
      {}, self.options().dtype(compute));
  if (compute == at::kFloat) {
    result.copy_(flat_out.reshape({}));
  } else {
    Narrow(flat_out, result, handle);
  }
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(MeanFn, mean_dispatcher, Backend::kCambricon, MeanKernelCambricon);

at::Tensor MeanDimKernelCambricon(
    const at::Tensor& self, at::OptionalIntArrayRef dim, bool keepdim,
    std::optional<at::ScalarType> dtype_opt) {
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: mean.dim requires a device tensor");
  TORCH_CHECK(
      SupportedFloatDtype(self.scalar_type()),
      "flagos cambricon: mean.dim does not serve ", self.scalar_type());
  TORCH_CHECK(
      !dtype_opt.has_value() || SupportedFloatDtype(*dtype_opt),
      "flagos cambricon: mean.dim does not serve the requested dtype");
  // aten's mean over an empty reduction is NaN; CNNL would answer 0. Refuse
  // rather than return a number aten never returns.
  const int64_t rank = self.dim();
  std::vector<int> axes;
  if (dim.has_value()) {
    for (const int64_t axis : *dim) {
      const int64_t normalised = axis < 0 ? axis + rank : axis;
      TORCH_CHECK(
          normalised >= 0 && normalised < rank,
          "flagos cambricon: mean.dim axis out of range: ", axis);
      TORCH_CHECK(
          self.size(normalised) > 0,
          "flagos cambricon: mean.dim over an empty axis is not served");
      axes.push_back(static_cast<int>(normalised));
    }
  } else {
    for (int64_t axis = 0; axis < rank; ++axis) {
      axes.push_back(static_cast<int>(axis));
    }
  }

  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(self.scalar_type());
  const auto input = self.contiguous();
  const auto wide_input = widen ? Widen(input, handle) : input;
  const auto compute = widen ? at::kFloat : self.scalar_type();

  std::vector<int64_t> out_shape;
  for (int64_t axis = 0; axis < rank; ++axis) {
    const bool reduced =
        std::find(axes.begin(), axes.end(), static_cast<int>(axis)) != axes.end();
    if (!reduced) {
      out_shape.push_back(self.size(axis));
    } else if (keepdim) {
      out_shape.push_back(1);
    }
  }
  if (out_shape.empty()) {
    out_shape.push_back(1);
  }
  auto wide_out = at::empty(out_shape, self.options().dtype(compute));

  cnnlReduceDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateReduceDescriptor(&desc), "cnnlCreateReduceDescriptor");
  CheckCnnl(
      cnnlSetReduceDescriptor_v3(
          desc, axes.data(), static_cast<int>(axes.size()), CNNL_REDUCE_AVG,
          ToCnnlDtype(compute), CNNL_NOT_PROPAGATE_NAN, CNNL_REDUCE_NO_INDICES,
          CNNL_32BIT_INDICES, /*p=*/0.0f, /*acc_sqrt=*/false),
      "cnnlSetReduceDescriptor_v3 (mean.dim)");
  TensorDesc in_desc, out_desc;
  in_desc.Set(wide_input);
  out_desc.Set(wide_out);

  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetReduceOpWorkspaceSize_v2(
          handle, in_desc.get(), out_desc.get(), /*indices_desc=*/nullptr, desc,
          &workspace_size),
      "cnnlGetReduceOpWorkspaceSize_v2 (mean.dim)");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  CheckCnnl(
      cnnlReduce_v2(
          handle, desc, in_desc.get(), wide_input.const_data_ptr(),
          /*alpha=*/nullptr, /*beta=*/nullptr,
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, out_desc.get(), wide_out.mutable_data_ptr(),
          /*indices_desc=*/nullptr, /*indices=*/nullptr),
      "cnnlReduce_v2 (mean.dim)");
  cnnlDestroyReduceDescriptor(desc);

  if (compute == at::kFloat) {
    return wide_out;
  }
  auto result = at::empty(out_shape, self.options().dtype(compute));
  Narrow(wide_out, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(MeanDimFn, mean_dim_dispatcher, Backend::kCambricon, MeanDimKernelCambricon);

at::Tensor MmKernelCambricon(const at::Tensor& self, const at::Tensor& mat2) {
  const at::ScalarType dtype = at::result_type(self, mat2);
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: mm does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1 &&
          mat2.device() == self.device(),
      "flagos cambricon: mm needs both operands on one device");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const bool widen = ComputesInFloat32(dtype);
  // A transposed operand is described, not copied. `x @ w.t()` is how every
  // Linear layer spells its product, and materialising that view copies the
  // whole weight on every call: measured at 1024x3072, mm(x, w.t()) took 9027 us
  // against 37 us for mm(x, w) -- 242 times slower for the same arithmetic.
  // CNNL expresses it with CNNL_MATMUL_DESC_TRANS* plus the operand's own
  // strides, so both are passed through instead of being normalised away.
  // This is the shape `x @ w.t()` takes in every Linear layer, and copying the
  // weight there made the multiply 242 times slower than the same product on a
  // contiguous operand.
  // A 2-D view whose transpose is contiguous is described by that storage plus
  // the matmul transpose flag; anything else is materialised.
  const bool a_transposed =
      self.dim() == 2 && !self.is_contiguous() && self.t().is_contiguous();
  const bool b_transposed =
      mat2.dim() == 2 && !mat2.is_contiguous() && mat2.t().is_contiguous();
  // With the transpose flag set, CNNL expects each descriptor to describe the
  // operand's *storage*, and applies the transpose itself. So a transposed
  // operand is passed as the contiguous view whose transpose is the logical
  // matrix -- for `w.t()` that view is `w`. The result shape still follows aten's
  // rules, which is why it is computed from the logical operands.
  const auto a = a_transposed ? self.t() : self.contiguous();
  const auto b = b_transposed ? mat2.t() : mat2.contiguous();
  const auto aw = widen ? Widen(a, handle) : a;
  const auto bw = widen ? Widen(b, handle) : b;

  std::vector<int64_t> out_shape(self.sizes().begin(), self.sizes().end());
  out_shape.back() = mat2.size(-1);
  const auto compute = widen ? at::kFloat : dtype;
  auto wide = at::empty(out_shape, self.options().dtype(compute));

  TensorDesc ad, bd, cd;
  ad.Set(aw);
  bd.Set(bw);
  cd.Set(wide);

  // alpha and beta are the compute dtype's 1 and 0: the operands were widened
  // to that dtype above, and CNNL reads the scale in the operand dtype.
  const float one_f = 1.0f;
  const float zero_f = 0.0f;
  const void* alpha = static_cast<const void*>(&one_f);
  const void* beta = static_cast<const void*>(&zero_f);

  // The transpose state lives on the Ex descriptor, set through
  // cnnlSetMatMulExDescAttrBase: the non-Ex setter returns BAD_PARAM on this
  // SDK, and cnnlMatMulEx_v2 reads transposes from here rather than from the
  // tensor descriptors. The algorithm must still come from the heuristic -- an
  // empty Ex algorithm descriptor fails with "Algorithm initialization failed".
  cnnlMatMulExDescriptor_t desc = nullptr;
  CheckCnnl(cnnlCreateMatMulExDescriptor(&desc), "cnnlCreateMatMulExDescriptor");
  CheckCnnl(
      cnnlSetMatMulExDescAttrBase(
          desc,
          a_transposed ? CNNL_MATMUL_OP_T : CNNL_MATMUL_OP_N,
          b_transposed ? CNNL_MATMUL_OP_T : CNNL_MATMUL_OP_N,
          /*use_beta=*/false, CNNL_MATMUL_EPI_NONE),
      "cnnlSetMatMulExDescAttrBase (mm)");
  cnnlMatMulExAlgo_t algo = nullptr;
  CheckCnnl(cnnlCreateMatMulExAlgo(&algo), "cnnlCreateMatMulExAlgo");
  cnnlMatMulExHeuristicResult_t result_algo = nullptr;
  CheckCnnl(
      cnnlCreateMatMulExHeuristicResult(&result_algo),
      "cnnlCreateMatMulExHeuristicResult");
  cnnlMatMulExPrefer_t prefer{};
  int returned = 0;
  CheckCnnl(
      cnnlGetMatMulExAlgoHeuristic(
          handle, desc, ad.get(), bd.get(), cd.get(), cd.get(), prefer,
          /*requested_algo_count=*/1, &result_algo, &returned),
      "cnnlGetMatMulExAlgoHeuristic (mm)");
  TORCH_CHECK(
      returned > 0, "flagos cambricon: no matmul algorithm for ", "{op");
  size_t workspace_size = 0;
  CheckCnnl(
      cnnlGetMatMulExHeuristicResult(result_algo, algo, &workspace_size),
      "cnnlGetMatMulExHeuristicResult");
  at::Tensor workspace;
  if (workspace_size > 0) {
    workspace = at::empty(
        {static_cast<int64_t>(workspace_size)},
        self.options().dtype(at::kByte));
  }
  CheckCnnl(
      cnnlMatMulEx_v2(
          handle, desc, algo, alpha, ad.get(), aw.const_data_ptr(), bd.get(),
          bw.const_data_ptr(), beta, cd.get(), wide.mutable_data_ptr(),
          workspace_size > 0 ? workspace.mutable_data_ptr() : nullptr,
          workspace_size, cd.get(), wide.mutable_data_ptr()),
      "cnnlMatMulEx_v2 (mm)");

  if (!widen) {
    return wide;
  }
  auto result = at::empty(out_shape, self.options());
  Narrow(wide, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(MmFn, mm_dispatcher, Backend::kCambricon, MmKernelCambricon);

at::Tensor MulScalarKernelCambricon(
    const at::Tensor& self, const at::Scalar& other) {
  const at::ScalarType dtype = at::result_type(self, other);
  TORCH_CHECK(
      SupportedFloatDtype(dtype) || dtype == at::kInt,
      "flagos cambricon: mul.Scalar does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: mul.Scalar requires a device tensor");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  const auto input = self.contiguous().to(dtype);
  const bool integral = dtype == at::kInt;
  const bool widen = !integral && ComputesInFloat32(dtype);
  const auto wide_input = widen ? Widen(input, handle) : input;
  const auto compute = integral ? dtype : at::kFloat;

  // The scalar becomes a one-element device tensor. A CNNL descriptor cannot
  // express rank zero, and cnnlOpTensor broadcasts a (1) operand across the
  // operand it is paired with, so this is the shape that carries a scalar.
  // The scalar operand is described at the input's own rank with size 1 on
  // every axis: cnnlOpTensor rejects an operand whose rank differs from the
  // output's (cnnlSetTensorDescriptor fails), and a leading-1 shape broadcasts
  // across every axis.
  std::vector<int64_t> scalar_shape(self.dim(), 1);
  if (scalar_shape.empty()) {
    scalar_shape.push_back(1);
  }
  TORCH_CHECK(
      !scalar_shape.empty() && scalar_shape.size() <= 8,
      "flagos cambricon: scalar rank ", scalar_shape.size(),
      " (input dim ", self.dim(), ")");
  // Filled from a host-side tensor copy: aten's in-place fill_ of a device
  // tensor dispatches through the same op set this backend is serving, so
  // building the scalar with it re-entered the kernel being defined.
  const double value = other.toDouble();
  auto host_scalar = at::empty(scalar_shape, at::kDouble);
  host_scalar.fill_(value);
  auto scalar = host_scalar.to(
      self.options().dtype(integral ? dtype : at::kFloat));

  auto output = at::empty(self.sizes(), self.options().dtype(compute));
  TensorDesc ad, bd, cd;
  ad.Set(wide_input);
  bd.Set(scalar);
  cd.Set(output);
  OpTensorDesc op(CNNL_OP_TENSOR_MUL, compute);
  const float one_f = 1.0f;
  const float zero_f = 0.0f;
  const int32_t one_i = 1;
  const int32_t zero_i = 0;
  const void* aa = integral ? static_cast<const void*>(&one_i) : &one_f;
  const void* bb = integral ? static_cast<const void*>(&zero_i) : &zero_f;
  CheckCnnl(
      cnnlOpTensor(
          handle, op.get(), aa, ad.get(), wide_input.const_data_ptr(), aa,
          bd.get(), scalar.const_data_ptr(), nullptr, 0, bb, cd.get(),
          output.mutable_data_ptr()),
      "cnnlOpTensor (mul.Scalar)");
  if (dtype == compute) {
    return output;
  }
  auto result = at::empty(self.sizes(), self.options().dtype(dtype));
  Narrow(output, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(MulScalarFn, mul_scalar_dispatcher, Backend::kCambricon, MulScalarKernelCambricon);

at::Tensor MulTensorKernelCambricon(
    const at::Tensor& self, const at::Tensor& other) {
  const at::ScalarType dtype = at::result_type(self, other);
  TORCH_CHECK(
      SupportedFloatDtype(dtype) || dtype == at::kInt,
      "flagos cambricon: mul.Tensor does not serve ", dtype);
  const auto device = self.is_cpu() ? other.device() : self.device();
  TORCH_CHECK(
      device.type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: mul.Tensor requires a device operand");
  for (const auto* tensor : {&self, &other}) {
    TORCH_CHECK(
        tensor->device() == device || (tensor->is_cpu() && tensor->dim() == 0),
        "flagos cambricon: mul.Tensor only accepts CPU tensors as scalars");
  }
  CambriconDeviceGuard guard(self.is_cpu() ? other : self);
  auto a = self.to(device, dtype);
  auto b = other.to(device, dtype);
  const auto shape = at::infer_size(self.sizes(), other.sizes());
  auto result = at::empty(shape, a.options());
  if (result.numel() == 0) {
    return result;
  }
  // A CNNL ARRAY descriptor cannot express rank zero.
  std::vector<int64_t> full(shape.begin(), shape.end());
  if (full.empty()) {
    full.push_back(1);
  }
  const auto handle = HandleForDevice(static_cast<int>(device.index()));
  const bool integral = dtype == at::kInt;
  const bool widen = !integral && ComputesInFloat32(dtype);
  // cnnlOpTensor broadcasts on its own: given [2,4,8] against [2,4,1] it
  // produces the [2,4,8] product (verified against a C probe), and it rejects a
  // reduced-rank or flattened descriptor with status 7. So each operand is
  // described at its own rank and nothing is expanded.
  //
  // Materialising the broadcast was how this was first written, and it copies a
  // result-sized buffer before the arithmetic starts: `add` of [2,512,1] against
  // [2,512,1024] measured 5809 us materialised against 24 us for the same add
  // without a broadcast.
  a = a.contiguous();
  b = b.contiguous();
  // A scalar operand arrives as a rank-0 tensor (`x * 2.0` spells the number
  // that way), and a CNNL descriptor cannot express rank zero. Describing it as
  // one element keeps the broadcast meaning: a single value applies to every
  // element of the other operand.
  const auto as_rank_one = [](const at::Tensor& t) {
    return t.dim() == 0 ? t.reshape({1}) : t;
  };
  const auto a_shaped = widen ? Widen(as_rank_one(a), handle) : as_rank_one(a);
  const auto b_shaped = widen ? Widen(as_rank_one(b), handle) : as_rank_one(b);
  const auto compute = integral ? dtype : at::kFloat;
  auto wide = at::empty(full, a.options().dtype(compute));
  TensorDesc ad, bd, cd;
  ad.Set(a_shaped);
  bd.Set(b_shaped);
  cd.Set(wide);
  OpTensorDesc op(CNNL_OP_TENSOR_MUL, compute);
  const float one = 1.0f;
  const float zero = 0.0f;
  const int32_t int_one = 1;
  const int32_t int_zero = 0;
  const void* scale_a = integral ? static_cast<const void*>(&int_one) : &one;
  const void* scale_b = integral ? static_cast<const void*>(&int_zero) : &zero;
  CheckCnnl(
      cnnlOpTensor(
          handle, op.get(), scale_a, ad.get(), a_shaped.const_data_ptr(),
          scale_a, bd.get(), b_shaped.const_data_ptr(), nullptr, 0, scale_b,
          cd.get(), wide.mutable_data_ptr()),
      "cnnlOpTensor (mul.Tensor)");
  if (dtype == compute) {
    return wide.reshape(shape);
  }
  auto output = result.reshape(full);
  Narrow(wide, output, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(MulTensorFn, mul_tensor_dispatcher, Backend::kCambricon, MulTensorKernelCambricon);

at::Tensor& MulOutKernelCambricon(
    const at::Tensor& self, const at::Tensor& other, at::Tensor& out) {
  auto result = MulTensorKernelCambricon(self, other);
  if (out.sizes() != result.sizes()) {
    out.resize_(result.sizes());
  }
  out.copy_(result);
  return out;
}

REGISTER_IMPL_TO_DISPATCHER(MulOutFn, mul_out_dispatcher, Backend::kCambricon, MulOutKernelCambricon);

at::Tensor NegKernelCambricon(const at::Tensor& self) {
  const at::ScalarType dtype = self.scalar_type();
  TORCH_CHECK(
      SupportedFloatDtype(dtype),
      "flagos cambricon: neg does not serve ", dtype);
  TORCH_CHECK(
      self.device().type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: neg requires a device tensor");
  CambriconDeviceGuard guard(self);
  const auto handle = HandleForDevice(static_cast<int>(self.device().index()));
  // The operand keeps its own strides. In a training step this op is reached
  // through a [B, heads, S, head_dim] transpose view, and gathering that view
  // into a dense buffer costs 15762 us against 13 us for the negation itself --
  // the copy was the whole cost. cnnlNegTensor documents strided descriptors
  // (cnnlSetTensorDescriptorEx), so the view is described as it is.
  //
  // A widening dtype has to be materialised anyway, because the cast produces a
  // dense tensor and there is nothing left to describe.
  const auto wide = Widen(self, handle);
  const bool strided = wide.data_ptr() == self.data_ptr();
  auto output = at::empty(self.sizes(), self.options().dtype(at::kFloat));
  TensorDesc in_desc, out_desc;
  if (strided) {
    in_desc.SetStrided(self);
  } else {
    in_desc.Set(wide);
  }
  out_desc.Set(output);
  CheckCnnl(
      cnnlNegTensor(
          handle, in_desc.get(), wide.const_data_ptr(), out_desc.get(),
          output.mutable_data_ptr()),
      "cnnlNegTensor (neg)");
  if (!ComputesInFloat32(dtype)) {
    return output;
  }
  auto result = at::empty(self.sizes(), self.options());
  Narrow(output, result, handle);
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(NegFn, neg_dispatcher, Backend::kCambricon, NegKernelCambricon);

at::Tensor OnesLikeKernelCambricon(
    const at::Tensor& self, std::optional<at::ScalarType> dtype_opt,
    std::optional<at::Layout> layout_opt, std::optional<at::Device> device_opt,
    std::optional<bool> pin_memory_opt,
    std::optional<at::MemoryFormat> memory_format_opt) {
  TORCH_CHECK(
      !layout_opt.has_value() || *layout_opt == at::kStrided,
      "flagos cambricon: ones_like only serves strided layout");
  TORCH_CHECK(
      !device_opt.has_value() ||
          device_opt->type() == c10::DeviceType::PrivateUse1,
      "flagos cambricon: ones_like only serves the flagos device");
  TORCH_CHECK(
      !pin_memory_opt.has_value() || !*pin_memory_opt,
      "flagos cambricon: ones_like does not serve pinned memory");
  // allocate_like honours the dtype/device/memory-format options the way the
  // aten schema asks, so the fill only has to write 1 into the result.
  auto result = at::empty_like(self);
  if (dtype_opt.has_value()) {
    result = result.to(*dtype_opt);
  }
  if (result.numel() > 0) {
    result.fill_(1);
  }
  return result;
}

REGISTER_IMPL_TO_DISPATCHER(OnesLikeFn, ones_like_dispatcher, Backend::kCambricon, OnesLikeKernelCambricon);

